"""Original toxicology: initial assessment, decontamination and common toxidromes."""
from qbank_authoring import question,ref
rows=[]
AH=ref('AHA special-circumstance resuscitation guidelines: toxicology, 2025','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-and-pediatric-special-circumstances-of-resuscitation/')
IC=ref('ISCCM position statement: approach to poisoning','https://pmc.ncbi.nlm.nih.gov/articles/PMC11369925/')
AC=ref('Clinical Toxicology Recommendations Collaborative activated charcoal guidance: 2026','https://doi.org/10.1080/15563650.2025.2609807')
AP=ref('US/Canada acetaminophen poisoning consensus: 2023','https://doi.org/10.1001/jamanetworkopen.2023.27739')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('An obtunded adult with an unknown overdose has slow shallow breathing and oxygen saturation 88%. What is the immediate priority?', 'Support airway and ventilation while rapidly checking glucose and reversible causes',[
 ('Give activated charcoal before respiratory support','An unprotected airway creates aspiration risk and decontamination cannot precede stabilization.'),('Wait for a urine toxicology panel to select treatment','Screens may be delayed, incomplete or misleading and do not guide immediate ventilation.'),('Obtain a full psychiatric history before physiological treatment','History is useful after immediate threats are addressed.')],
 'Physiology comes before identifying every tablet','**Hypoventilation can be fatal before a specific poison is confirmed.**',['Provide oxygen and effective assisted ventilation as needed.','A point-of-care glucose and ECG can immediately identify treatable problems.'],'**Use targeted antidotes alongside resuscitation when indicated.**',['Ask about timing, formulations, coingestants and access to medications.','Consult toxicology early for severe or uncertain exposures.'],[['Airway/breathing','Immediate support'],['Bedside tests','Glucose and ECG'],['Identification','Concurrent targeted investigation']],[IC],style='clinical_scenario')

q('Which ingestion is least likely to benefit from activated charcoal because of poor adsorption?', 'Lithium carbonate',[
 ('Carbamazepine','Charcoal can adsorb this drug in suitable selected circumstances.'),('Phenobarbital','Charcoal can adsorb it; multiple-dose treatment may enhance elimination in selected severe cases.'),('Amitriptyline','It is adsorbable, although clinical risk and airway protection determine use.')],
 'Adsorption depends on the substance','**Charcoal is not a universal oral antidote.**',['Lithium, iron and simple alcohols are poorly adsorbed.','Timing, formulation, dose and aspiration risk determine expected net benefit.'],'**Choose decontamination after substance-specific risk assessment.**',['Do not administer charcoal to an unprotected airway.','Other techniques also require indication and contraindication assessment.'],[['Lithium','Poor adsorption'],['Many organic drugs','Potential adsorption'],['Decision','Risk-benefit rather than routine use']],[IC,AC])

q('A somnolent patient with a significant adsorbable-drug ingestion has no airway reflexes. Which statement about activated charcoal is correct?', 'It should not be given through an unprotected airway',[
 ('A nasogastric tube by itself prevents aspiration','The tube does not protect the trachea.'),('Charcoal is harmless if aspirated because it is not absorbed','Pulmonary aspiration can cause severe injury.'),('The ingestion dose alone overrides airway safety','Potential adsorption benefit does not remove the aspiration hazard.')],
 'Delivery into the stomach does not guarantee airway safety','**Depressed consciousness changes the decontamination risk-benefit balance.**',['Resuscitation and airway management take priority.','Intubation decisions should reflect overall clinical need and anticipated course.'],'**Use poison-specific guidance after stabilization.**',['Consider elapsed time and sustained-release formulations.','Avoid routine decontamination without a plausible clinical benefit.'],[['Unprotected airway','High aspiration risk'],['NG tube','Does not protect airway'],['Priority','Stabilization']],[AC],style='clinical_scenario')

q('Which sustained-release overdose may be considered for whole-bowel irrigation after toxicology assessment when the bowel is functioning and the airway is safe?', 'A substantial sustained-release verapamil ingestion',[
 ('A trivial immediate-release dose with no toxicity risk','The procedural burden is not justified by negligible risk.'),('Any ingestion in a patient with ileus','Ileus is a major contraindication to effective/safe bowel irrigation.'),('A corrosive ingestion solely to neutralize mucosal injury','Irrigation is not chemical neutralization of a caustic burn.')],
 'Whole-bowel irrigation has a narrow selected role','**Polyethylene-glycol electrolyte solution can reduce retained gastrointestinal drug burden in selected exposures.**',['Sustained-release products, some metals and body packing are potential indications.','Evidence for patient-important benefit is limited and risks remain.'],'**Exclude obstruction, ileus, perforation and unstable physiology.**',['Do not delay antidotes or organ support.','Use specialist advice for the formulation and expected course.'],[['Potential indication','Significant sustained-release exposure'],['Major barrier','Ileus/obstruction or unsafe airway'],['Role','Selected decontamination']],[IC])

q('A patient has agitation, hyperthermia, mydriasis and tachycardia. Dry flushed skin, urinary retention and reduced bowel sounds favor which toxidrome?', 'Antimuscarinic poisoning',[
 ('Sympathomimetic poisoning','This more often causes sweating and preserved/increased gastrointestinal activity.'),('Cholinergic poisoning','This produces secretions, sweating and gastrointestinal hyperactivity.'),('Opioid poisoning','Typical findings are respiratory depression and reduced consciousness, often with miosis.')],
 'Autonomic findings discriminate overlapping agitation syndromes','**Dryness, retention and reduced bowel activity support muscarinic blockade.**',['Antihistamines and several psychotropic agents can produce the pattern.','Mixed ingestions may add seizures or sodium-channel cardiotoxicity.'],'**Control agitation, temperature and complications with ECG-guided assessment.**',['Physostigmine requires careful selection and expert input, particularly if conduction toxicity is possible.','Do not diagnose from pupil size alone.'],[['Antimuscarinic','Dry skin and retention'],['Sympathomimetic','Diaphoresis'],['Cholinergic','Wet secretory syndrome']],[IC],style='clinical_scenario')

q('Which neuromuscular finding most strongly supports serotonin toxicity over an uncomplicated antimuscarinic syndrome?', 'Inducible or spontaneous clonus with hyperreflexia',[
 ('Urinary retention with absent bowel sounds','This points toward an antimuscarinic pattern.'),('Uniform lead-pipe rigidity with relative hyporeflexia','This is more suggestive of neuroleptic malignant syndrome in the right setting.'),('Isolated pinpoint pupils and bradypnea','This favors opioid toxicity.')],
 'Examine the neuromuscular system in a febrile agitated patient','**Clonus and hyperreflexia are key serotonin-toxicity clues.**',['Drug combinations and recent dose changes are important.','Severe rigidity can make clonus harder to demonstrate.'],'**Stop serotonergic agents and provide sedation, cooling and organ support according to severity.**',['Benzodiazepines are useful for agitation and muscle activity.','Antipyretics do not correct heat production from excessive muscle activity.'],[['Serotonin toxicity','Clonus/hyperreflexia'],['Antimuscarinic','Dryness/retention'],['NMS','Different exposure and rigidity pattern']],[IC])

q('A patient with a pulse has suspected opioid toxicity and severe hypoventilation. What is the appropriate therapeutic target for titrated naloxone?', 'Restoration of adequate ventilation and airway protection',[
 ('Complete abrupt arousal in every opioid-dependent patient','Excessive reversal can precipitate severe withdrawal without additional respiratory benefit.'),('Normalization of pupil size before any other endpoint','Pupil size is not the primary resuscitation target.'),('Elimination of all circulating opioid','Naloxone antagonizes receptors; it does not remove the drug.')],
 'Treat the respiratory danger','**Naloxone reverses opioid receptor effects but does not substitute for ventilation.**',['Assist breathing while preparing and titrating the antidote.','Long-acting opioids may outlast naloxone.'],'**Monitor for recurrent sedation and repeat dosing or infusion when indicated.**',['Look for coingestants if response is incomplete.','Cardiac arrest still requires standard CPR and ventilation without delay.'],[['Target','Adequate ventilation'],['Mechanism','Receptor antagonism'],['Later risk','Recurrent respiratory depression']],[AH],style='clinical_scenario')

q('Why is routine flumazenil inappropriate in an unknown mixed overdose with possible chronic benzodiazepine use?', 'It can precipitate withdrawal seizures and unmask proconvulsant coingestant toxicity',[
 ('It reliably reverses opioid receptor effects','Naloxone is the opioid antagonist.'),('It prevents seizures caused by tricyclic antidepressants','Reversal of benzodiazepine effects may remove seizure protection.'),('It removes benzodiazepines through the kidney','It is a receptor antagonist rather than an elimination treatment.')],
 'A reversible sedative effect may be safer than indiscriminate antagonism','**Flumazenil has a selective role rather than routine use in undifferentiated coma.**',['Dependence and proconvulsant coingestions increase risk.','Supportive airway management is often appropriate.'],'**Reserve use for carefully selected low-risk circumstances.**',['Consider iatrogenic isolated sedation and expert advice.','Do not delay oxygenation or ventilation while debating an antidote.'],[['Dependence','Withdrawal seizure risk'],['Mixed overdose','Proconvulsant toxicity may emerge'],['Usual foundation','Supportive care']],[AH])

q('A pesticide-exposed patient has bronchorrhea, bradycardia, sweating, diarrhea and fasciculations. Which mechanism best explains this syndrome?', 'Acetylcholinesterase inhibition causing muscarinic and nicotinic excess',[
 ('Pure muscarinic receptor antagonism','This causes dry rather than secretory findings.'),('Isolated beta-adrenergic stimulation','This does not explain the combined secretory and fasciculation pattern.'),('Selective opioid receptor agonism','This does not account for the cholinergic secretions and neuromuscular findings.')],
 'Recognize the wet cholinergic syndrome','**Organophosphates inhibit acetylcholinesterase.**',['Muscarinic effects include airway secretions and bronchoconstriction.','Nicotinic effects include fasciculations and weakness.'],'**Protect staff, decontaminate appropriately and support breathing while giving atropine.**',['Remove contaminated clothing using appropriate protection.','Clinical treatment must not wait for cholinesterase assay results.'],[['Muscarinic','Secretions/bronchospasm'],['Nicotinic','Fasciculation/weakness'],['Priority','Respiratory support and antidotal treatment']],[IC,AH],style='clinical_scenario')

q('During atropine treatment of severe organophosphate poisoning, which endpoint is most useful?', 'Improvement in bronchial secretions, air entry and perfusion',[
 ('Pupil dilation alone','Pupil size can lag or be affected by direct ocular exposure.'),('A fixed total dose irrespective of response','Requirements vary widely and can be very large.'),('Complete disappearance of nicotinic paralysis','Atropine does not directly reverse neuromuscular-junction weakness.')],
 'Titrate to the dangerous muscarinic physiology','**A drying, better ventilated chest and improving hemodynamics are more meaningful than pupil size.**',['Tachycardia alone does not prove adequate treatment if bronchorrhea persists.','Respiratory failure may also involve nicotinic weakness and central effects.'],'**Continue ventilatory support and reassess the need for an atropine infusion.**',['Oxime decisions depend on the agent, timing and specialist protocol.','Atropine toxicity and recurrent cholinergic toxicity require ongoing distinction.'],[['Atropine target','Muscarinic respiratory/perfusion effects'],['Not a reliable sole endpoint','Pupil size'],['Persistent weakness','May require ventilation']],[IC,AH])
